from pathlib import Path

SCRIPT_DIR = Path(__file__).resolve().parent


def locate_repository():
    candidates = []
    for base in (Path.cwd().resolve(), SCRIPT_DIR):
        candidates.extend((base, base / "kalshi-qss-bot"))
        for parent in base.parents:
            candidates.extend((parent, parent / "kalshi-qss-bot"))
    seen = set()
    for candidate in candidates:
        candidate = candidate.resolve()
        if candidate in seen:
            continue
        seen.add(candidate)
        registry = candidate / "qseries_v2" / "oracle_terminal" / "oracle_terminal_interactive_command_registry.py"
        runner = candidate / "run_oracle_open_intelligence_terminal.py"
        test = candidate / "test_oit_031_oracle_terminal_interactive_command_registry.py"
        if registry.is_file() and runner.is_file() and test.is_file():
            return candidate
    raise SystemExit("[ERROR] Could not locate current Q Series repository.")


